css:
.article-preview { color: var(--color-article-ink); }
.article-preview .article-body { max-width: 42rem; margin: 0 auto; padding: 1.5rem 1.25rem 3rem; font-size: 1rem; line-height: 1.85; }
.article-preview .article-body h1,
.article-preview .article-body h2,
.article-preview .article-body h3,
.article-preview .article-body h4,
.article-preview .article-body h5,
.article-preview .article-body h6 { color: var(--color-article-heading); font-weight: 700; margin: 2rem 0 0.875rem; }
.article-preview .article-body h5 { font-size: 0.9375rem; line-height: 1.65; }
.article-preview .article-body h6 { font-size: 0.875rem; line-height: 1.65; color: var(--color-article-muted); }
.article-preview .article-body p,
.article-preview .article-body ul,
.article-preview .article-body ol,
.article-preview .article-body blockquote,
.article-preview .article-body pre,
.article-preview .article-body table,
.article-preview .article-body figure { margin: 1.125rem 0; }
.article-preview .article-body a { color: var(--color-article-heading); text-decoration: underline; text-underline-offset: 0.2em; }
.article-preview .article-body strong { color: var(--color-article-heading); font-weight: 700; }
.article-preview .article-body del { color: var(--color-article-muted); }
.article-preview .article-body blockquote p { margin: 0.375rem 0; }
.article-preview .article-body ul { padding-left: 1.5rem; }
.article-preview .article-body ol { padding-left: 1.5rem; }
.article-preview .article-body li + li { margin-top: 0.375rem; }
.article-preview .article-body hr { border: 0; border-bottom: 0.0625rem solid var(--color-article-line); margin: 2.5rem 0; }
.article-preview .article-body code { background: var(--color-article-code-tint); color: var(--color-article-code); border-radius: 0.25rem; font-size: 0.875em; padding: 0.125em 0.375em; }
.article-preview .article-body pre { background: var(--color-article-code-surface); border-radius: 0; color: var(--color-article-code-tint); overflow-x: auto; padding: 1rem; font-size: 0.875rem; line-height: 1.75; }
.article-preview .article-body pre code { background: transparent; color: inherit; padding: 0; }
.article-preview .article-body table { border-collapse: collapse; display: block; max-width: 100%; overflow-x: auto; font-size: 0.875rem; line-height: 1.75; }
.article-preview .article-body th,
.article-preview .article-body td { border: 0.0625rem solid var(--color-article-line); padding: 0.625rem 0.75rem; text-align: left; vertical-align: top; }
.article-preview .article-body th { background: var(--color-article-tint); color: var(--color-article-heading); font-weight: 700; border-top: 0.125rem solid var(--color-article-heading); }
.article-preview .article-body img { border-radius: 0; height: auto; max-width: 100%; display: block; }
.article-preview .article-body figcaption { color: var(--color-article-muted); font-size: 0.8125rem; line-height: 1.65; margin-top: 0.625rem; text-align: center; }
.article-preview .article-body input[type='checkbox'] { accent-color: var(--color-article-accent); margin: 0 0.5rem 0 0; }
.article-preview .article-body h1 { font-size: 2.125rem; line-height: 1.4; font-weight: 800; letter-spacing: -0.02em; border-bottom: 0.25rem solid var(--color-article-heading); padding-bottom: 1.125rem; margin-bottom: 1.75rem; }
.article-preview .article-body h2 { display: inline-block; max-width: 100%; font-size: 1.375rem; line-height: 1.5; font-weight: 800; color: var(--color-article-quote-surface); background: var(--color-article-heading); padding: 0.5rem 0.875rem; margin-top: 2.5rem; }
.article-preview .article-body h3 { font-size: 1.125rem; line-height: 1.6; font-weight: 800; border-bottom: 0.1875rem double var(--color-article-heading); padding-bottom: 0.5rem; }
.article-preview .article-body h4 { font-size: 1rem; line-height: 1.65; font-weight: 800; border-left: 0.1875rem solid var(--color-article-heading); padding-left: 0.625rem; letter-spacing: 0.025em; }
.article-preview .article-body blockquote { border-left: 0.125rem solid var(--color-article-heading); background: var(--color-article-quote-surface); color: var(--color-article-ink); padding: 0.25rem 1.125rem; margin: 1.75rem 0; }
.article-preview .article-body > :first-child { margin-top: 0; }
